do $$ declare initial jsonb; latest jsonb; replay jsonb; saved_payload jsonb; begin
  initial:=public.get_names_workspace();
  if initial->'workspace'<>'null'::jsonb then raise exception 'new_account_not_empty'; end if;
  select payload into saved_payload from names_qualification where label='a';
  initial:=public.save_names_workspace(0,'dddddddd-dddd-4ddd-8ddd-999999999991',saved_payload);
  if (initial#>>'{workspace,revision}')::integer<>1 or initial#>'{workspace,payload}'<>saved_payload then raise exception 'initial_save_mismatch'; end if;
  if public.get_names_workspace()<>initial then raise exception 'reload_mismatch'; end if;
  latest:=public.save_names_workspace(1,'dddddddd-dddd-4ddd-8ddd-999999999992',jsonb_set(saved_payload,'{ui,query}','"later save"'));
  replay:=public.save_names_workspace(0,'dddddddd-dddd-4ddd-8ddd-999999999991',saved_payload);
  if replay<>initial or public.get_names_workspace()<>latest then raise exception 'replay_changed_current'; end if;
  begin
    perform public.save_names_workspace(1,'dddddddd-dddd-4ddd-8ddd-999999999993',saved_payload);
    raise exception 'stale_save_was_accepted';
  exception when sqlstate 'PT409' then null; end;
  begin
    perform public.save_names_workspace(0,'dddddddd-dddd-4ddd-8ddd-999999999991',jsonb_set(saved_payload,'{ui,query}','"changed retry"'));
    raise exception 'changed_retry_was_accepted';
  exception when sqlstate 'PT409' then null; end;
  begin
    update public.names_workspaces set owner_id=gen_random_uuid();
    raise exception 'raw_update_was_accepted';
  exception when insufficient_privilege then null; end;
  begin
    perform * from fluid_private.names_workspace_requests;
