do $$ declare saved jsonb; begin
  if public.get_names_workspace()->'workspace'<>'null'::jsonb then raise exception 'cross_owner_read'; end if;
  if exists(select 1 from public.names_workspaces) then raise exception 'rls_cross_owner_read'; end if;
  select public.save_names_workspace(0,'dddddddd-dddd-4ddd-8ddd-999999999991',payload) into saved from names_qualification where label='b';
  if saved#>>'{workspace,id}'=(select first_receipt#>>'{workspace,id}' from names_qualification where label='a') then raise exception 'cross_owner_identity'; end if;
end $$;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{}',true);
do $$ begin
  begin perform public.get_names_workspace(); raise exception 'missing_identity_accepted'; exception when insufficient_privilege then null; end;
