reset role;
do $$ declare role_name text; begin
  if not (select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in('public.names_workspaces'::regclass,'fluid_private.names_workspace_requests'::regclass)) then raise exception 'rls_not_forced'; end if;
  if has_schema_privilege('authenticated','fluid_private','USAGE') then raise exception 'private_schema_exposed'; end if;
  foreach role_name in array array['anon','service_role'] loop
